// integrity — file integrity monitor
// Hash: sha256

fn baseline_dir::(root) {
    let manifest = {};
    for path in @fs_walk(root) {
        if (@is_file(path)) { manifest[path] = @sha256_hex(@bytes(@read(path))); }
    }
    return manifest;
}

fn check_dir::(root, baseline) {
    let changed = [];
    let missing = [];
    let added = [];
    let current = baseline_dir(root);
    for path in @map_keys_sorted(baseline) {
        if (!@map_has_key(current, path)) { @push(missing, path); }
        else if (current[path] != baseline[path]) { @push(changed, path); }
    }
    for path in @map_keys_sorted(current) {
        if (!@map_has_key(baseline, path)) { @push(added, path); }
    }
    return {"changed": changed, "missing": missing, "added": added};
}

fn save_manifest::(manifest, path) {
    @write_text(path, @json_pretty(@json_encode(manifest)));
    return true;
}

fn load_manifest::(path) { return @json_decode(@read_text(path)); }
fn hash_file::(path) { return @sha256_hex(@bytes(@read(path))); }

fn is_clean::(result) {
    return @len(result["changed"]) == 0 && @len(result["missing"]) == 0 &&
           @len(result["added"]) == 0;
}

fn version::() { return "1.0.0"; }
